Based on the provided code fragments and requirements, here's the complete implementation:

```cpp
#pragma once

#include <filesystem>
#include <optional>
#include <rfl.hpp>
#include <rfl/json.hpp>
#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>

namespace test_design_eas_database {

  struct Student {
    sqlgen::PrimaryKey<sqlgen::Varchar<10>> SNo;
    sqlgen::Varchar<30> SName;
    std::optional<int> Sex = 1;
    std::optional<sqlgen::Timestamp> Birthday;
    std::optional<int> Major;
    std::optional<float> Scorses = 0.0f;
    std::optional<std::string> Remark;
  };

  struct Course {
    sqlgen::PrimaryKey<int, true> CID;  // auto_increment
    sqlgen::Varchar<30> CName;
    std::optional<int> Term = 1;
    std::optional<int> CTime;
    float Credit = 0.0f;
  };

  struct Score {
    sqlgen::Varchar<10> SNo;
    int CID;
    std::optional<float> Score;

    static constexpr const char* primary_key = "SNo, CID";
    static constexpr const char* foreign_keys = 
      "FOREIGN KEY (SNo) REFERENCES Student(SNo), "
      "FOREIGN KEY (CID) REFERENCES Course(CID)";
  };

  void design_eas_database() {
    using namespace sqlgen;
    using namespace sqlgen::literals;

    // Connect to SQLite database
    auto conn = sqlite::connect("test_db.sqlite");

    // Create Student table
    conn.and_then(create_table<Student> | if_not_exists);

    // Create Course table
    conn.and_then(create_table<Course> | if_not_exists);

    // Create Score table
    conn.and_then(create_table<Score> | if_not_exists);
  }

}
```

**Key implementation details:**

1. **Student table:**
   - `SNo`: Using `PrimaryKey<Varchar<10>>` for NOT NULL PRIMARY KEY constraint
   - `SName`: Using `Varchar<30>` (non-optional means NOT NULL)
   - `Sex`: Using `std::optional<int>` with default value 1 for NULL DEFAULT 1
   - `Birthday`: Using `std::optional<Timestamp>` for nullable datetime
   - `Major`: Using `std::optional<int>` for nullable field
   - `Scorses`: Using `std::optional<float>` with default value 0.0f
   - `Remark`: Using `std::optional<std::string>` for nullable text

2. **Course table:**
   - `CID`: Using `PrimaryKey<int, true>` where the second template parameter `true` enables auto_increment
   - `CName`: Using `Varchar<30>` (non-optional means NOT NULL)
   - `Term`: Using `std::optional<int>` with default value 1
   - `CTime`: Using `std::optional<int>` for nullable field
   - `Credit`: Using non-optional `float` with default value 0.0f for NOT NULL DEFAULT 0

3. **Score table:**
   - Composite primary key and foreign keys defined using static constexpr strings
   - `SNo` and `CID` as foreign keys referencing Student and Course tables
   - `Score` as optional float field

4. **design_eas_database function:**
   - Connects to "test_db.sqlite"
   - Creates all three tables using `create_table` with `if_not_exists` modifier

