# Complete File

```cpp
#pragma once

#include <ranges>
#include <rfl.hpp>
#include <rfl/json.hpp>
#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace batch_insert_products {

struct Product {
  sqlgen::PrimaryKey<int> product_id;
  std::string name;
  float price;
  std::string category;
  int stock;
};

/**
 * Function: Perform efficient batch insertion of product data using a transaction.
 * 
 * @param products List of products to insert
 * @return true if all inserts succeed, false otherwise
 */
bool batch_insert_products(const std::vector<Product>& products) {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to SQLite database
  auto result = sqlgen::sqlite::connect("test_db.sqlite")
    // Drop table if exists
    .and_then(drop<Product> | if_exists)
    // Create the Product table
    .and_then(create_table<Product> | if_not_exists)
    // Begin transaction
    .and_then(begin_transaction)
    // Insert products
    .and_then(insert(std::ref(products)))
    // Commit transaction
    .and_then(commit);

  // Return true if successful, false otherwise
  return result.has_value();
}

}  // namespace batch_insert_products
```

