```cpp
#pragma once

#include <filesystem>
#include <optional>
#include <rfl.hpp>
#include <rfl/json.hpp>
#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>

namespace test_design_eas_database {

  struct Student {
    sqlgen::PrimaryKey<sqlgen::Varchar<10>> SNo;
    sqlgen::Varchar<30> SName;
    std::optional<int> Sex = 1;
    std::optional<sqlgen::Timestamp> Birthday;
    std::optional<int> Major;
    std::optional<float> Scorses = 0.0f;
    std::optional<std::string> Remark;
  };

  struct Course {
    sqlgen::PrimaryKey<int, true> CID;  // auto_increment = true
    sqlgen::Varchar<30> CName;
    std::optional<int> Term = 1;
    std::optional<int> CTime;
    float Credit = 0.0f;
  };

  struct Score {
    sqlgen::Varchar<10> SNo;
    int CID;
    std::optional<float> Score;

    // Define composite primary key
    using PrimaryKey = rfl::Field<"SNo", sqlgen::Varchar<10>>,
                       rfl::Field<"CID", int>;

    // Define foreign keys
    static constexpr auto foreign_keys = std::tuple{
      sqlgen::ForeignKey<"SNo", Student, "SNo">{},
      sqlgen::ForeignKey<"CID", Course, "CID">{}
    };
  };

  void design_eas_database() {
    using namespace sqlgen;
    using namespace sqlgen::literals;

    // Connect to SQLite database
    const auto conn = sqlite::connect("test_db.sqlite");

    // Create Student table
    conn.and_then(create_table<Student> | if_not_exists);

    // Create Course table
    conn.and_then(create_table<Course> | if_not_exists);

    // Create Score table
    conn.and_then(create_table<Score> | if_not_exists);
  }

}
```

