Looking at the task and the provided code fragments, I need to implement a function that:
1. Connects to SQLite database "test_db.sqlite"
2. Creates User and Post tables
3. Finds users who posted between 2025-12-01 and 2025-12-31
4. Returns results as vector of ActiveUser

Based on the code fragments and the sqlgen library patterns, here's the complete implementation:

```cpp
#pragma once

#include <optional>
#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>
#include <chrono>
#include <iomanip>
#include <sstream>

namespace query_active_users_posts {

struct User {
  sqlgen::PrimaryKey<int> user_id;
  std::string username;
};

struct Post {
  sqlgen::PrimaryKey<int> post_id;
  int user_id;
  sqlgen::DateTime created_at;
};

struct ActiveUser {
  static constexpr const char* tablename = "ActiveUserView";
  static constexpr bool is_view = true;
  sqlgen::PrimaryKey<int> user_id;
  std::string username;
};

/**
 * Description: This function returns a list of active users who have posted within the last year.
 * Returns: std::vector<ActiveUser>.
 */
std::vector<ActiveUser> query_active_users_posts() {
    using namespace sqlgen;
    using namespace sqlgen::literals;

    // Connect to the SQLite database
    auto conn = sqlite::connect("test_db.sqlite");

    // Create tables if they don't exist
    conn.and_then(create_table<User> | if_not_exists)
        .and_then(create_table<Post> | if_not_exists);

    // Query for active users who posted between 2025-12-01 and 2025-12-31
    auto result = conn.and_then(
        select_from<User>(
            "user_id"_c,
            "username"_c
        ) 
        | join<Post>(on("user_id"_c))
        | where(
            "created_at"_c >= "2025-12-01" and 
            "created_at"_c <= "2025-12-31"
        )
        | distinct()
        | to<std::vector<ActiveUser>>
    );

    // Return the result or an empty vector if there was an error
    if (result) {
        return result.value();
    } else {
        return std::vector<ActiveUser>();
