Based on the provided code fragments and the function signature, I need to implement a function that queries a customer's purchase history from a SQLite database using the `sqlgen` library. Looking at the examples, I can see the pattern for creating queries with joins.

Here's the complete file:

```cpp
#pragma once

#include <ranges>
#include <rfl.hpp>
#include <rfl/json.hpp>
#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace query_customer_purchase_history {

struct Customer {
  sqlgen::PrimaryKey<int> customer_id;
  std::string name;
  std::string email;
};

struct Product {
  sqlgen::PrimaryKey<int> product_id;
  std::string name;
  double price;
};

struct Order {
  sqlgen::PrimaryKey<int> order_id;
  sqlgen::ForeignKey<int, Customer, "customer_id"> customer_id;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> order_date;
  double total_amount;
};

struct OrderItem {
  sqlgen::PrimaryKey<int> item_id;
  sqlgen::ForeignKey<int, Order, "order_id"> order_id;
  sqlgen::ForeignKey<int, Product, "product_id"> product_id;
  int quantity;
};

struct PurchaseHistory {
  std::string product_name;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> order_date;
  int quantity;
};

/**
 * Function: Retrieve a customer's purchase history with product details.
 * 
 * @param customer_id ID of the customer to query
 * @return List of purchase history items
 */
std::vector<PurchaseHistory> query_customer_purchase_history(int customer_id) {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Build the query using select_from with joins
  const auto get_purchase_history =
      select_from<Customer, "c">("name"_p | as<"product_name">,
                                 "order_date"_o | as<"order_date">,
                                 "quantity"_oi | as<"quantity">) |
      join<Order, "o">("customer_id"_c == "customer_id"_o) |
      join<OrderItem, "oi">("order_id"_o == "order_id"_oi) |
      join<Product, "p">("product_id"_oi == "product_id"_p) |
      where("customer_id"_c == customer_id) |
      order_by("order_date"_o.desc()) |
      to<std::vector<PurchaseHistory>>;

  // Connect to the database and execute the query
  return sqlite::connect("test_db.sqlite")
      .and_then(get_purchase_history)
      .value();
}

}  // namespace query_customer_purchase_history
```

The implementation:

1. **Uses `select_from` with table aliases**: Creates a query starting from the `Customer` table with alias "c"
2. **Selects the required fields**: Maps `Product.name` to `product_name`, `Order.order_date` to `order_date`, and `OrderItem.quantity` to `quantity`
3. **Joins all tables**: Uses `join` to connect Customer → Order → OrderItem → Product following the foreign key relationships
4. **Filters by customer_id**: Uses `where` clause to filter results for the specific customer
5. **Orders results**: Orders by `order_date` in descending order (most recent first)
6. **Maps to result type**: Uses `to<std::vector<PurchaseHistory>>` to map the query results to the desired struct
7. **Connects to database**: Uses `sqlite::connect("test_db.sqlite")` to connect to the specified database file
8. **Executes and returns**: Chains the query execution and extracts the value

