output.text:
Looking at the code fragments and the structure provided, I need to implement a function that:
1. Connects to SQLite database "test_db.sqlite"
2. Performs a JOIN between Order and Customer tables
3. Filters orders with total_amount > 1000
4. Orders by total_amount descending
5. Returns a vector of OrderView structs

Based on the patterns from the test files, here's the complete implementation:

```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <string>
#include <vector>

namespace query_high_value_orders {

struct Customer {
  sqlgen::PrimaryKey<int> customer_id;
  std::string name;
};

struct Order {
  sqlgen::PrimaryKey<int> order_id;
  int customer_id;
  double total_amount;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> order_date;
};

struct OrderView {
  static constexpr const char* tablename = "HighValueOrderView";
  static constexpr bool is_view = true;
  sqlgen::PrimaryKey<int> order_id;
  std::string name;
  double total_amount;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> order_date;
};

std::vector<OrderView> query_high_value_orders() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to the SQLite database and execute the query
  const auto result = 
      sqlite::connect("test_db.sqlite")
          .and_then(exec(R"(
              SELECT o.order_id, c.name, o.total_amount, o.order_date
              FROM "Order" o
              INNER JOIN Customer c ON o.customer_id = c.customer_id
              WHERE o.total_amount > 1000
              ORDER BY o.total_amount DESC
          )") | to<std::vector<OrderView>>)
          .value();

  return result;
}

}  // namespace query_high_value_orders
```

