However, I notice that the current `UserProfile` struct definition doesn't properly handle all the constraints mentioned in the SQL. I need to:
- Add `NotNull` wrapper for fields
- Add `Check` constraint for age
- Add `Default` wrapper for created_at and is_verified
- Use proper string types with length constraints

Here's the complete file:

```cpp
#pragma once

#include <ranges>
#include <rfl.hpp>
#include <rfl/json.hpp>
#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace schema_create_complex_table {

struct UserProfile {
  sqlgen::PrimaryKey<int, sqlgen::auto_incr> user_id;
  sqlgen::Unique<sqlgen::NotNull<sqlgen::Varchar<50>>> username;
  sqlgen::Unique<sqlgen::NotNull<sqlgen::Varchar<100>>> email;
  sqlgen::Check<int, "age >= 18"> age;
  sqlgen::Text bio;
  sqlgen::Default<sqlgen::DateTime, sqlgen::current_timestamp> created_at;
  sqlgen::Default<bool, false> is_verified;
};

/**
 * Function: Create a table with various constraints and data types.
 * @return true if creation succeeds, false otherwise
 */
bool create_complex_table() {
  try {
    using namespace sqlgen;

    // Connect to SQLite database
    auto conn_result = sqlgen::sqlite::connect("test_db.sqlite");

    if (!conn_result) {
      return false;
    }

    auto conn = std::move(conn_result.value());

    // Create the UserProfile table
    auto result = conn.and_then(drop<UserProfile> | if_exists)
                      .and_then(create_table<UserProfile>);

    return result.has_value();
  } catch (...) {
    return false;
  }
}

}  // namespace schema_create_complex_table
```

