output.text:
Looking at the code fragments and the task requirements, I need to implement a function that performs schema migration by adding columns to an existing SQLite table. Here's the complete implementation:

```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>

namespace schema_migration_add_column {

struct User {
  sqlgen::PrimaryKey<int> user_id;
  std::string username;
};

struct UserAfter {
  sqlgen::PrimaryKey<int, sqlgen::auto_incr> user_id;
  std::string username;
  std::string phone_number;
  bool is_active;
};

/**
 * Function: Perform schema migration to add new columns.
 * @return true if migration succeeds, false otherwise
 */
bool migration_add_column() {
  // Connect to the SQLite database
  auto conn_result = sqlgen::sqlite::connect("test_db.sqlite");

  if (!conn_result) {
    return false;
  }

  auto conn = std::move(conn_result.value());

  // SQL statements to add new columns
  const std::string add_phone_sql = 
      "ALTER TABLE User ADD COLUMN phone_number VARCHAR(20)";
  const std::string add_is_active_sql = 
      "ALTER TABLE User ADD COLUMN is_active INTEGER DEFAULT 1";

  // Execute first ALTER TABLE statement
  auto result1 = conn.execute(add_phone_sql);
  if (!result1) {
    // Check if the error is because column already exists
    // If so, we can continue (idempotent operation)
    const auto& error_msg = result1.error().what();
    if (std::string(error_msg).find("duplicate column name") == std::string::npos) {
      return false;
    }
  }

  // Execute second ALTER TABLE statement
  auto result2 = conn.execute(add_is_active_sql);
  if (!result2) {
    // Check if the error is because column already exists
    const auto& error_msg = result2.error().what();
    if (std::string(error_msg).find("duplicate column name") == std::string::npos) {
      return false;
    }
  }

  return true;
}

} // namespace schema_migration_add_column
```

This implementation:

1. **Connects to the database**: Uses `sqlgen::sqlite::connect()` to connect to "test_db.sqlite"
2. **Handles connection errors**: Returns `false` if connection fails
3. **Executes ALTER TABLE statements**: Adds both `phone_number` and `is_active` columns
4. **Handles errors gracefully**: Checks for "duplicate column name" errors, which occur when columns already exist, making the operation idempotent
5. **Returns success status**: Returns `true` if migration succeeds (or columns already exist), `false` for other errors

The function uses the `Connection::execute()` method which is shown in the code fragments to execute raw SQL statements against the SQLite database.

