#pragma once

#include <optional>
#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <string>

namespace upsert_user_profile {

struct UserProfile {
  sqlgen::PrimaryKey<int> user_id;
  std::optional<std::string> bio;
  std::optional<std::string> avatar_url;
};

/**
 * @brief Insert or update a user profile in the database.
 *
 * @param u The user profile to insert or update.
 * @return true If the operation is successful.
 * @return false If the operation fails.
 */
bool upsert_user_profile(const UserProfile& u) {
  using namespace sqlgen;
  auto conn = sqlite::connect("test_db.sqlite");
  if (!conn) return false;

  create_table<UserProfile>(conn);

  // Insert using sqlgen::insert_or_replace for PK/Unique presence
  return insert_or_replace(std::vector{u})(conn).has_value();
}

} // namespace upsert_user_profile

test cases:
#include <gtest/gtest.h>
#include "upsert_user_profile.hpp"

namespace upsert_user_profile {

TEST(sqlite, upsert_user_profile) {
  using namespace sqlgen;
  auto conn = sqlite::connect("test_db.sqlite").value();
  drop<UserProfile>(conn);
  create_table<UserProfile>(conn);

  UserProfile u1{.user_id = 1, .bio = "first", .avatar_url = "a1.png"};
  ASSERT_TRUE(upsert_user_profile(u1));
  auto rows1 = sqlgen::read<std::vector<UserProfile>>(conn).value();
  ASSERT_EQ(rows1.size(), 1u);
  EXPECT_EQ(rows1[0].bio.value(), "first");

  UserProfile u2{.user_id = 1, .bio = "second", .avatar_url = "a2.png"};
  ASSERT_TRUE(upsert_user_profile(u2));
  auto rows2 = sqlgen::read<std::vector<UserProfile>>(conn).value();
  ASSERT_EQ(rows2.size(), 1u);
  EXPECT_EQ(rows2[0].bio.value(), "second");
  EXPECT_EQ(rows2[0].avatar_url.value(), "a2.png");
}

}  // namespace upsert_user_profile

