  EXPECT_NE(sql.find("JOIN"), std::string::npos);
  EXPECT_NE(sql.find("WHERE"), std::string::npos);
  EXPECT_NE(sql.find("ORDER BY"), std::string::npos);
  EXPECT_NE(sql.find("LIMIT"), std::string::npos);
}

