#include <gtest/gtest.h>
#include "read_single_record_by_id.hpp"

namespace read_single_record_by_id {

TEST(sqlite, read_single_record_by_id) {
  using namespace sqlgen;

  auto conn = sqlite::connect("test_db.sqlite").value();
  drop<Customer>(conn);
  create_table<Customer>(conn);

  std::vector<Customer> customers = {
      {1, "Alice", "alice@example.com"},
      {2, "Bob", "bob@example.com"},
      {3, "Charlie", "charlie@example.com"},
  };
  insert(conn, customers);

  auto c = read_single_record_by_id(2);

  EXPECT_EQ(c.customer_id.value(), 2);
  EXPECT_EQ(c.name, "Bob");
  EXPECT_EQ(c.email, "bob@example.com");
}

}  // namespace read_single_record_by_id

