std::vector<UpdatedNote> replace_text_in_notes() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to the SQLite database
  const auto conn = sqlite::connect("test_db.sqlite");

  // Execute raw SQL to replace "foo" with "bar" in content column
  conn.and_then([](const auto& c) {
    return c.execute("UPDATE Note SET content = REPLACE(content, 'foo', 'bar')");
  });

  // Read the updated notes
  const auto notes = sqlgen::read<std::vector<Note>>(conn).value();

  // Map to UpdatedNote structs
  std::vector<UpdatedNote> result;
  for (const auto& note : notes) {
    result.push_back(UpdatedNote{
      .note_id = note.note_id,
      .updated_content = note.content
    });
  }

  return result;
}

}  // namespace replace_text_in_notes
