Looking at the code fragments and the task requirements, I need to implement a function that demonstrates cascade delete behavior in SQLite. Based on the examples, I can see how the `sqlgen` library works.

Here's the complete implementation:

```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>

namespace cascade_delete_demo {

struct Parent {
  sqlgen::PrimaryKey<int> parent_id;
  std::string name;
};

struct Child {
  sqlgen::PrimaryKey<int> child_id;
  sqlgen::ForeignKey<int, Parent, "parent_id"> parent_id;
  std::string note;
};

/**
 * Demonstrates cascade delete behavior in SQLite using foreign key constraints.
 * @param parent_id The ID of the parent record to delete.
 * Returns: true if the cascade delete worked as expected, false otherwise.
 */
bool cascade_delete_demo(int parent_id) {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to the database
  auto conn = sqlgen::sqlite::connect("test_db.sqlite");

  // Enable foreign key support in SQLite (required for cascade delete)
  conn = conn.and_then([](auto c) {
    return c.execute("PRAGMA foreign_keys = ON;").and_then([c]() { return c; });
  });

  // Drop existing tables if they exist and create fresh ones
  conn = conn.and_then(drop<Child> | if_exists)
             .and_then(drop<Parent> | if_exists)
             .and_then(create_table<Parent>)
             .and_then(create_table<Child>);

  // Insert parent record
  const auto parent = Parent{.parent_id = parent_id, .name = "Test Parent"};
  conn = sqlgen::write(conn, parent);

  // Insert child records with the same parent_id
  const auto children = std::vector<Child>{
      Child{.child_id = 1, .parent_id = parent_id, .note = "Child 1"},
      Child{.child_id = 2, .parent_id = parent_id, .note = "Child 2"},
      Child{.child_id = 3, .parent_id = parent_id, .note = "Child 3"}
  };
  conn = sqlgen::write(conn, children);

  // Verify children were inserted
  auto children_before = sqlgen::read<std::vector<Child>>(conn);
  if (!children_before || children_before.value().size() != 3) {
    return false;
  }

  // Delete parent record
  const auto delete_parent = delete_from<Parent> | 
                             where("parent_id"_c == parent_id);
  conn = conn.and_then(delete_parent);

  // Verify that children were automatically deleted (cascade)
  auto children_after = sqlgen::read<std::vector<Child>>(conn);
  if (!children_after) {
    return false;
  }

  // If cascade delete worked, there should be no children left
  return children_after.value().empty();
}

}  // namespace cascade_delete_demo
```

This implementation:

1. **Connects** to the SQLite database "test_db.sqlite"
2. **Enables foreign keys** with `PRAGMA foreign_keys = ON` (required for cascade delete in SQLite)
3. **Creates tables** by dropping existing ones and creating fresh Parent and Child tables
4. **Inserts data** - one parent record and three child records linked to it
5. **Deletes the parent** using the `delete_from` operation with a where clause
6. **Verifies cascade behavior** by checking if child records were automatically deleted
7. **Returns true** if all child records were deleted (cascade worked), **false** otherwise

The foreign key constraint is defined in the `Child` struct using `sqlgen::ForeignKey<int, Parent, "parent_id">`, which creates the relationship with CASCADE DELETE behavior.

