namespace column_is_null_checks {

TEST(sqlite, column_is_null_checks) {
  using namespace sqlgen;
  auto conn = sqlite::connect("test_db.sqlite").value();
  drop<Profile>(conn);
  create_table<Profile>(conn);
  insert(conn, std::vector<Profile>{
      {1, "A", std::nullopt, std::nullopt},
      {2, "B", "bio", std::nullopt},
      {3, "C", std::nullopt, "url"},
      {4, "D", "bio", "url"}});

  auto results = column_is_null_checks();
  ASSERT_GE(results.size(), 3);
}

}  // namespace column_is_null_checks

