#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>

namespace update_set_operations {

struct Account {
  sqlgen::PrimaryKey<int> account_id;
  double balance;
  std::string status;
};

/**
 * description: update_set_operations.
 * sets the balance and status of an Account identified by acc_id.
 * @param acc_id: The id of Account to be updated.
 * @returns true if the update operations are successful, and false otherwise.
 */
bool update_set_operations(int acc_id) {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  auto conn_res = sqlite::connect("test_db.sqlite");
  if (!conn_res) return false;
  auto conn = conn_res.value();

  create_table<Account>(conn);

  auto res1 = (update<Account>("balance"_c.set(100.0)) |
               where("account_id"_c == acc_id))(conn);
  if (!res1) return false;

  auto res2 = (update<Account>("status"_c.set("active")) |
               where("account_id"_c == acc_id))(conn);
  return res2.has_value();
}

}  // namespace update_set_operations

