namespace full_join_suppliers_products {

TEST(sqlite, full_join_suppliers_products) {
  using namespace sqlgen;
  auto conn = sqlite::connect("test_db.sqlite").value();
  drop<Supplier>(conn);
  drop<Product>(conn);
  create_table<Supplier>(conn);
  create_table<Product>(conn);

  insert(conn, std::vector<Supplier>{{1, "S1"}, {2, "S2"}});
  insert(conn, std::vector<Product>{{1, 1, "P1"}, {2, 3, "OrphanP"}});

  auto rows = full_join_suppliers_products();
  ASSERT_GE(rows.size(), 2);
}

}  // namespace full_join_suppliers_products

