Looking at the code fragments and the task requirements, I need to implement a FULL JOIN between Suppliers and Products tables. Since SQLite doesn't support FULL JOIN natively, I'll need to use a UNION of LEFT JOIN and RIGHT JOIN (or simulate it).

Here's the complete implementation:

```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>
#include <optional>

namespace full_join_suppliers_products {

struct Supplier {
  sqlgen::PrimaryKey<int> supplier_id;
  std::string name;
};

struct Product {
  sqlgen::PrimaryKey<int> product_id;
  int supplier_id;
  std::string name;
};

struct SupProd {
  std::string supplier_name;
  std::optional<std::string> product_name;
};

/**
 * Returns a vector of SupProd structs, where each struct contains the name of a supplier and the name of a product, if any.
 */
std::vector<SupProd> full_join_suppliers_products() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to the SQLite database
  auto conn = sqlite::connect("test_db.sqlite");

  // Since SQLite doesn't support FULL JOIN natively, we need to simulate it
  // using UNION of LEFT JOIN and a query for unmatched products

  // Execute raw SQL for FULL JOIN simulation
  const std::string sql = R"(
    SELECT s.name AS supplier_name, p.name AS product_name
    FROM Supplier s
    LEFT JOIN Product p ON s.supplier_id = p.supplier_id
    UNION
    SELECT NULL AS supplier_name, p.name AS product_name
    FROM Product p
    LEFT JOIN Supplier s ON p.supplier_id = s.supplier_id
    WHERE s.supplier_id IS NULL
  )";

  // Execute the query and fetch results manually
  auto result = conn.and_then([&sql](auto& connection) -> Result<std::vector<SupProd>> {
    std::vector<SupProd> results;

    auto stmt_result = connection.prepare_statement(sql);
    if (!stmt_result) {
      return stmt_result.error();
    }

    auto stmt = std::move(stmt_result.value());

    while (true) {
      auto step_result = connection.step(stmt.get());
      if (!step_result) {
        break;
      }

      SupProd row;

      // Get supplier_name (column 0)
      const unsigned char* supplier_name_ptr = sqlite3_column_text(stmt.get(), 0);
      if (supplier_name_ptr != nullptr) {
        row.supplier_name = reinterpret_cast<const char*>(supplier_name_ptr);
      } else {
        row.supplier_name = "";
      }

      // Get product_name (column 1)
      const unsigned char* product_name_ptr = sqlite3_column_text(stmt.get(), 1);
      if (product_name_ptr != nullptr) {
        row.product_name = reinterpret_cast<const char*>(product_name_ptr);
      } else {
        row.product_name = std::nullopt;
      }

      results.push_back(row);
    }

    return results;
  });

  return result.value_or(std::vector<SupProd>{});
}

}  // namespace full_join_suppliers_products
```

