ground truth:
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <string>

namespace concat_function {

struct Person {
  sqlgen::PrimaryKey<int> id;
  std::string first_name;
  std::string last_name;
};

struct FullName {
  std::string full_name;
};

/**
 * This function queries the full names of all persons in the `Person` table.
 * Returns: std::vector<FullName>.
 */
inline std::vector<FullName> concat_function() {
    using namespace sqlgen;
    using namespace sqlgen::literals;
    auto query = select_from<Person>(
        concat("first_name"_c, " ", "last_name"_c) | as<"full_name">
        ) | to<std::vector<FullName>>;
    return query(sqlite::connect("test_db.sqlite").value()).value();
}

}  // namespace concat_function

test cases:
#include <gtest/gtest.h>
#include "concat_function.hpp"

namespace concat_function {

TEST(concat_function, test_query_generation) {
    using namespace std;
    using namespace sqlgen;
    using namespace sqlgen::literals;

    vector<Person> persons = {
        {1, "John", "Doe"},
        {2, "Jane", "Smith"},
        {3, "Alice", "Johnson"}
    };

    auto conn = sqlite::connect("test_db.sqlite").value();
    drop<Person>(conn);
    create_table<Person>(conn);
    insert(conn, persons);

    vector<FullName> query_result = concat_function();
    EXPECT_EQ(query_result.size(), 3);
    EXPECT_EQ(query_result[0].full_name, "John Doe");
    EXPECT_EQ(query_result[1].full_name, "Jane Smith");
    EXPECT_EQ(query_result[2].full_name, "Alice Johnson");
}

}

