#include <gtest/gtest.h>
#include "in_operator_usage.hpp"

namespace in_operator_usage {

TEST(in_operator_usage, test_query_generation) {
    using namespace sqlgen;
    using namespace sqlgen::literals;
    auto conn = sqlite::connect("test_db.sqlite").value();
    std::vector<Status> status = {
        {1, 1},
        {2, 2},
        {3, 3},
        {4, 4},
    };
    drop<Status>(conn);
    create_table<Status>(conn);
    insert(conn, status);
    auto rows = in_operator_usage();
    ASSERT_GE(rows.size(), 3);
}

}

related functions.definition:
template <class ConditionType>
inline auto where(const ConditionType& _cond) {
  return Where<std::remove_cvref_t<ConditionType>>{.condition = _cond};
};

template <rfl::internal::StringLiteral _name>
auto operator"" _c() {
  return Col<_name>{};
}

template <class... Ts>
auto in(const Ts&... _ts) const noexcept {
  return transpilation::make_condition(transpilation::conditions::in(
      transpilation::Col<_name, _alias>{}, _ts...));
}

template <class... ColTypes>
friend auto operator|(const Read& _r, const OrderBy<ColTypes...>&) {
  static_assert(
      std::is_same_v<OrderByType, Nothing>,
      "You cannot call order_by(...) twice (but you can order by more "
      "than one column).");
  static_assert(std::is_same_v<LimitType, Nothing>,
                "You cannot call limit(...) before order_by.");
  static_assert(sizeof...(ColTypes) != 0,
                "You must assign at least one column to order by(...).");
  return Read<Type, WhereType,
              transpilation::order_by_t<
                  transpilation::value_t<Type>, Nothing,
                  typename std::remove_cvref_t<ColTypes>::ColType...>,
              LimitType>{.where_ = _r.where_};
}

friend auto operator|(const Read& _r, const Limit& _limit) {
    static_assert(std::is_same_v<LimitType, Nothing>,
                  "You cannot call limit(...) twice.");
    return Read<Type, WhereType, OrderByType, Limit>{.where_ = _r.where_,
                                                     .limit_ = _limit};
  }

