Based on the code fragments, particularly `tests/sqlite/test_create_index.cpp` and `tests/mysql/test_create_index_dry.cpp`, I can see how to create an index using the sqlgen library.

Here's the complete implementation:

```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <string>

namespace create_index_basic {

struct Book {
  sqlgen::PrimaryKey<int> id;
  std::string title;
};

/**
 * This function returns a SQL string to create an index named `idx_book_title` on the `title` column of `Book`.
 */
inline std::string create_index_basic() {
    using namespace sqlgen;
    using namespace sqlgen::literals;

    // Create the index query on the title column
    const auto query = create_index<"idx_book_title", Book>("title"_c);

    // Convert to SQL string using sqlite's to_sql
    return sqlite::to_sql(query);
}

}  // namespace create_index_basic
