Looking at the requirements and the code fragments, I need to:

1. Create a view `OrderSummaryView` that joins Order and OrderItem tables
2. Read data from that view
3. Return the results as a vector of `OrderSummary` structs

Based on the code fragments, I can see how to:
- Connect to SQLite using `sqlgen::sqlite::connect()`
- Execute SQL using the connection's `execute()` method
- Use `sqlgen::read<std::vector<T>>()` to read data from a table/view
- Chain operations using `.and_then()`

Here's the complete implementation:

```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace create_view_order_summary {

struct Order {
  sqlgen::PrimaryKey<int> order_id;
  std::string customer;
};

struct OrderItem {
  sqlgen::PrimaryKey<int> item_id;
  int order_id;
  double unit_price;
  int quantity;
};

struct OrderSummary {
  static constexpr const char* tablename = "OrderSummaryView";
  static constexpr bool is_view = true;
  sqlgen::PrimaryKey<int> order_id;
  std::string customer;
  double total;
};

/**
 * Description: Create a view `OrderSummaryView` that shows order ID, customer name, and (unit_price * quantity) as total price for each order.
 * Returns: std::vector<OrderSummary>.
 */
std::vector<OrderSummary> create_view_order_summary() {
    using namespace sqlgen;

    // SQL to create the view
    const std::string create_view_sql = 
        "CREATE VIEW IF NOT EXISTS OrderSummaryView AS "
        "SELECT o.order_id, o.customer, SUM(oi.unit_price*oi.quantity) as total "
        "FROM Order o INNER JOIN OrderItem oi ON o.order_id=oi.order_id "
        "GROUP BY o.order_id, o.customer;";

    // Connect to database, create view, and read data
    auto result = sqlite::connect("test_db.sqlite")
        .and_then([&create_view_sql](auto conn) {
            return conn.execute(create_view_sql).transform([conn]() { return conn; });
        })
        .and_then(read<std::vector<OrderSummary>>);

    // Return the result or empty vector on error
    if (result) {
        return result.value();
    } else {
        return std::vector<OrderSummary>{};
    }
}

}  // namespace create_view_order_summary
```

