Looking at the task and the code fragments provided, I need to implement a function that:

1. Connects to SQLite database "test_db.sqlite"
2. Performs an inner join between Project and TimeLog tables
3. Extracts temporal components from start_time
4. Calculates duration in days between start_time and end_time
5. Returns results as a vector of TimeMetrics

Based on the code examples, I can see the pattern of how `sqlgen` library works with its fluent API using `and_then`, `select_from`, temporal functions, and the pipe operator.

Here's the complete implementation:

```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace project_time_tracking {

struct Project {
  sqlgen::PrimaryKey<int> project_id;
  std::string name;
};

struct TimeLog {
  sqlgen::PrimaryKey<int> log_id;
  int project_id;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> start_time;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> end_time;
};

struct TimeMetrics {
  sqlgen::PrimaryKey<int> project_id;
  std::string name;
  int day;
  int month;
  int year;
  int hour;
  int minute;
  int second;
  double duration_days;
};

/**
 * Description: This function tracks time metrics for each project, including day, month, year, hour, minute, second, and duration in days.
 * Returns: std::vector<TimeMetrics>.
 */
std::vector<TimeMetrics> project_time_tracking() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Define the query to join Project and TimeLog, extract temporal components,
  // and calculate duration
  const auto query = 
      select_from<Project>(
          "project_id"_c.as<"project_id">(),
          "name"_c.as<"name">(),
          day(join<TimeLog>("project_id"_c, "start_time"_c)).as<"day">(),
          month(join<TimeLog>("project_id"_c, "start_time"_c)).as<"month">(),
          year(join<TimeLog>("project_id"_c, "start_time"_c)).as<"year">(),
          hour(join<TimeLog>("project_id"_c, "start_time"_c)).as<"hour">(),
          minute(join<TimeLog>("project_id"_c, "start_time"_c)).as<"minute">(),
          second(join<TimeLog>("project_id"_c, "start_time"_c)).as<"second">(),
          days_between(
              join<TimeLog>("project_id"_c, "start_time"_c),
              join<TimeLog>("project_id"_c, "end_time"_c)
          ).as<"duration_days">()
      ) | 
      inner_join<TimeLog>(on("project_id"_c)) |
      to<std::vector<TimeMetrics>>;

  // Connect to the database and execute the query
  const auto result = sqlite::connect("test_db.sqlite")
                          .and_then(query)
                          .value();

  return result;
}

}  // namespace project_time_tracking
```

