Looking at the code fragments and the structure of the `sqlgen` library, I need to implement a function that:

1. Connects to SQLite database `test_db.sqlite`
2. Creates a table `Target` from `Source` where `value > 100` using CREATE TABLE AS SELECT
3. Returns the data as `std::vector<Target>`

Based on the examples, I can see the pattern of using `sqlgen` operations with the pipe operator and `.and_then()` for chaining operations.

Here's the complete implementation:

```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <string>

namespace create_table_as_select {

struct Source {
  sqlgen::PrimaryKey<int> id;
  int value;
};

struct Target {
  int value;
};

/**
 * Description: This function creates a table `Target` from a select query on `Source` 
 * Returns: std::vector<Target>.
 */
inline std::vector<Target> create_table_as_select() {
    using namespace sqlgen;
    using namespace sqlgen::literals;

    // Connect to the SQLite database
    auto conn = sqlite::connect("test_db.sqlite").value();

    // Drop Target table if it exists (to ensure clean state)
    (drop<Target> | if_exists)(conn);

    // Create Target table from Source where value > 100
    // Using CREATE TABLE AS SELECT pattern
    const auto create_query = 
        create_table<Target> | 
        from(select_from<Source>("value"_c) | where("value"_c > 100));

    // Execute the CREATE TABLE AS SELECT
    create_query(conn);

    // Read and return all records from Target
    return sqlgen::read<std::vector<Target>>(conn).value();
}

}  // namespace create_table_as_select
